    // Time - O(nm)
    func findSubsrtingNaive(string: String, pattern: String) {
        let stringLength = string.count
        let patternLength = pattern.count
        for i in 0..<stringLength - patternLength - 1 {
            var counter: Int = 0
            while counter < patternLength {
                if string[i + counter] != pattern[counter] {
                    break
                }
                counter += 1
            }
            if counter == patternLength {
                print("Found at index - \(i)")
            }
        }
    }

    // O(n)
    func reverseStringTwoPointers(string: inout String) {
        var left = 0, right = string.count - 1
        while left < right {
            var temp = string[left]
            string[left] = string[right]
            string[right] = temp
            left += 1
            right -= 1
        }
    }

    // O(n)
    func checkIsPalindrome(string: String) -> Bool {
        var left = 0, right = string.count - 1
        while left < right {
            guard string[left] == string[right] else { return false }

            left += 1
            right -= 1

        }
        return true
    }

    func checkIsPalindrome(string: String, left: Int, right: Int) -> Bool {
        var left = left
        var right = right
        while left < right {
            guard string[left] == string[right] else { return false }

            left += 1
            right -= 1

        }
        return true
    }

    /*
     415. Add Strings

     Given two non-negative integers, num1 and num2 represented as string, return the sum of num1 and num2 as a string.

     You must solve the problem without using any built-in library for handling large integers (such as BigInteger). You must also not convert the inputs to integers directly.



     Example 1:

     Input: num1 = "11", num2 = "123"
     Output: "134"
     Example 2:

     Input: num1 = "456", num2 = "77"
     Output: "533"
     Example 3:

     Input: num1 = "0", num2 = "0"
     Output: "0"


     Constraints:

     1 <= num1.length, num2.length <= 104
     num1 and num2 consist of only digits.
     num1 and num2 don't have any leading zeros except for the zero itself.
     */
    func addStrings(_ num1: String, _ num2: String) -> String {
        var result = ""
        var count1 = num1.count - 1
        var count2 = num2.count - 1
        let zeroAscii = Int(Character("0").asciiValue!)
        var carry: Int = 0
        while count1 >= 0 || count2 >= 0 {
            let char1 = Int((count1 >= 0 ? num1[String.Index(utf16Offset: count1, in: num1)] : Character("0")).asciiValue!) - zeroAscii
            let char2 = Int((count2 >= 0 ? num2[String.Index(utf16Offset: count2, in: num2)] : Character("0")).asciiValue!) - zeroAscii
            let sum = (char1 + char2 + carry) % 10
            carry = (char1 + char2 + carry) / 10
            result.append("\(sum)")
            count1 -= 1
            count2 -= 1
        }
        if carry != 0 {
            result.append("\(carry)")
        }
        
        return String(result.reversed())
        
    }
    /*
     125. Valid Palindrome

     A phrase is a palindrome if, after converting all uppercase letters into lowercase letters and removing all non-alphanumeric characters, it reads the same forward and backward. Alphanumeric characters include letters and numbers.

     Given a string s, return true if it is a palindrome, or false otherwise.



     Example 1:

     Input: s = "A man, a plan, a canal: Panama"
     Output: true
     Explanation: "amanaplanacanalpanama" is a palindrome.
     Example 2:

     Input: s = "race a car"
     Output: false
     Explanation: "raceacar" is not a palindrome.
     Example 3:

     Input: s = " "
     Output: true
     Explanation: s is an empty string "" after removing non-alphanumeric characters.
     Since an empty string reads the same forward and backward, it is a palindrome.


     Constraints:

     1 <= s.length <= 2 * 105
     s consists only of printable ASCII characters.
     */
    func isPalindrome(_ s: String) -> Bool {
        let char = Array(s)
        var i = 0
        var j = char.count - 1
        while i < j {
            if !(char[i].isNumber || char[i].isLetter) {
                i += 1
            } else if !(char[j].isNumber || char[j].isLetter) {
                j -= 1
            } else if char[i].lowercased() != char[j].lowercased() {
                return false
            } else {
                i += 1
                j -= 1
            }
        }
        return true

    }

    /*
     680. Valid Palindrome II

     Given a string s, return true if the s can be palindrome after deleting at most one character from it.



     Example 1:

     Input: s = "aba"
     Output: true
     Example 2:

     Input: s = "abca"
     Output: true
     Explanation: You could delete the character 'c'.
     Example 3:

     Input: s = "abc"
     Output: false


     Constraints:

     1 <= s.length <= 105
     s consists of lowercase English letters.


     */

    // wrong solution
    func validPalindrome(_ s: String) -> Bool {
        let array = Array(s)
        var i = 0
        var j = array.count - 1
        var count = 0
        while i < j {
            if array[i] != array[j] {
                count += 1
                if count > 1 {
                    return false
                }
            }
            i += 1
            j -= 1
        }
        return count == 1 && array.count == 3 ? false : true

    }
    /*
     Given a string s having lowercase characters, find the length of the longest substring without repeating characters.
     Input: s = “geeksforgeeks”
     Output: 7
     Explanation: The longest substrings without repeating characters are “eksforg” and “ksforge”, with lengths of 7.


     Input: s = “aaa”
     Output: 1
     Explanation: The longest substring without repeating characters is “a”


     Input: s = “abcdefabcbb”
     Output: 6
     Explanation: The longest substring without repeating characters is “abcdef”.
     */

    /*
     Given a non-empty string s and a dictionary wordDict containing a list of non-empty words,
     determine if s can be segmented into a space-separated sequence of one or more dictionary words.

     Note:

     The same word in the dictionary may be reused multiple times in the segmentation.
     You may assume the dictionary does not contain duplicate words.
     Example 1:

     Input: s = "leetcode", wordDict = ["leet", "code"]
     Output: true
     Explanation: Return true because "leetcode" can be segmented as "leet code".
     Example 2:

     Input: s = "applepenapple", wordDict = ["apple", "pen"]
     Output: true
     Explanation: Return true because "applepenapple" can be segmented as "apple pen apple".
                  Note that you are allowed to reuse a dictionary word.
     Example 3:

     Input: s = "catsandog", wordDict = ["cats", "dog", "sand", "and", "cat"]
     Output: false

     Example 4:
     Input: s = "bb", wordDict = ["a","b","bbb","bbbb"]
     Output: false
     */

    /**
    Big O Annotation
    Time complexity O(n) where n is the amount of elements in nums.
    Space complexity O(n) where n is the amount of elements in nums.
    */
    // This is not a correct solution
    func wordBreak(string: String, wordDictionary: [String]) -> Bool {

        var string = string

        for element in wordDictionary {
            let replaced = string.replacingOccurrences(of: element, with: "")
            if replaced == string {
                return false
            }
            string = replaced
        }

        return string.isEmpty
    }
    
    func wordBreak(s: String, wordDict: [String]) -> Bool {
        let wordSet = Set(wordDict)
        let n = s.count
        var dp = Array(repeating: false, count: n + 1)
        dp[0] = true
        
        let chars = Array(s)
        
        for i in 1...n {
            for j in 0..<i {
                let substring = String(chars[j..<i])
                if dp[j] && wordSet.contains(substring) {
                    dp[i] = true
                    break
                }
            }
        }
        
        return dp[n]
    }
    /*
     Given a string s, find the length of the longest substring without duplicate characters.
     Example 1:
     Input: s = "abcabcbb"
     Output: 3
     Explanation: The answer is "abc", with the length of 3.

     Example 2:
     Input: s = "bbbbb"
     Output: 1
     Explanation: The answer is "b", with the length of 1.

     Example 3:
     Input: s = "pwwkew"
     Output: 3
     Explanation: The answer is "wke", with the length of 3.
     Notice that the answer must be a substring, "pwke" is a subsequence and not a substring.


     Constraints:

     0 <= s.length <= 5 * 104
     s consists of English letters, digits, symbols and spaces.
     */
    // Converting String to char array and vice versa works faster in leet code than using String.Index

    func lengthOfLongestSubstring(_ s: String) -> Int {
        if s.count < 2 {
            return s.count
        }
        var hashSet = Set<Character>()
        var leftIndex = 0
        var rightIndex = 0
        var maxCount = 0
        let array = Array(s)
        while rightIndex < s.count {
            let rightChar = array[rightIndex]
            if hashSet.contains(rightChar) {
                let leftChar = array[leftIndex]
                hashSet.remove(leftChar)
                leftIndex += 1
            } else {
                hashSet.insert(rightChar)
                rightIndex += 1
                maxCount = max(maxCount, hashSet.count)
            }
        }

        return maxCount
    }

    func longestSubstringOptimized(string: String) -> Int {
        if string.count < 2 {
            return string.count
        }
        var hashSet = [Character: Int]()
        var leftIndex = 0
        var rightIndex = 0
        var maxCount = 0
        let stringArray = Array(string)
        while rightIndex < stringArray.count {
//            let rightChar = stringArray[rightIndex]
            let rightChar = string[String.Index(utf16Offset: rightIndex, in: string)]
            if let pair = hashSet[rightChar], pair >= leftIndex {
                leftIndex = pair + 1
            }
            hashSet[rightChar] = rightIndex
            rightIndex += 1
            maxCount = max(maxCount, rightIndex - leftIndex)
        }

        return maxCount
    }

    func lengthOfLongestSubstringOptimized(_ s: String) -> Int {
        if s.count < 2 {
            return s.count
        }
        var hashSet = [Character: Int]()
        var leftIndex = 0
        var rightIndex = 0
        var maxCount = 0
        while rightIndex < s.count {
            let rightChar = s[String.Index(utf16Offset: rightIndex, in: s)]
            if let pair = hashSet[rightChar], pair >= leftIndex {
                leftIndex = pair + 1
            }
            hashSet[rightChar] = rightIndex
            rightIndex += 1
            maxCount = max(maxCount, rightIndex - leftIndex)
        }

        return maxCount
    }

    // Time limit exceedes
    func lengthOfLongestSubstringStringIndex(_ s: String) -> Int {
        if s.count < 2 {
