    func swapCharacters(in charArray: inout [Character]) {
        swapCharacters(in: &charArray, left: 0, right: charArray.count - 1)
        func swapCharacters(in charArray: inout [Character], left: Int, right: Int) {
            guard left < right  else { return }
            charArray.swapAt(left, right)
            swapCharacters(in: &charArray, left: left + 1, right: right - 1)
