    // For a given string find all the possible palindrome substrings
    // For a given string s, partition it in such a way that every substring of the partition is a palindrome. Return all possible palindrome partioning of s
    // Ex
    // Input - "aab"
    // Output - [["a", "a", b"], ["aa", "b"]]

    func partitionPalindrome(string: String) -> [[String]] {
        var result = [[String]]()
        let charArray = Array(string)
        let s1 = String(charArray[0..<charArray.count])
        result.append([s1])

        partitionPalindromeRecursion(result: &result, string: string, index: 0, current: [])
        return result
    }
    func partitionPalindromeRecursion(result: inout [[String]], string: String, index: Int, current: [String]) {
        if index == string.count {
            result.append(current)
            return
        }
        var current = current
        for i in index..<string.count {
            let firstSubstring = String(Array(string)[index...i])

            if checkIsPalindrome(string: firstSubstring) {
                current.append(firstSubstring)
                partitionPalindromeRecursion(result: &result, string: string, index: i + 1, current: current)
                current.remove(at: current.count - 1)
            }
        }
    }

    /*
     Write a function to find the longest common prefix string amongst an array of strings.

     If there is no common prefix, return an empty string "".



     Example 1:

     Input: strs = ["flower","flow","flight"]
     Output: "fl"
     Example 2:

     Input: strs = ["dog","racecar","car"]
     Output: ""
     Explanation: There is no common prefix among the input strings.


     Constraints:

     1 <= strs.length <= 200
     0 <= strs[i].length <= 200
     */

    func longestCommonPrefix(_ strs: [String]) -> String {
        if strs.count < 2 {
            return strs[0]
        }
        var commonPrefix = strs[0]
        for i in 1..<strs.count {
            commonPrefix = getCommonPrefix(string1: commonPrefix, string2: strs[i])
            if commonPrefix.isEmpty {
                break
            }
        }
        return commonPrefix
    }
    func getCommonPrefix(string1: String, string2: String) -> String {
        var commonPrefix = ""
        let string1Array = Array(string1)
        let string2Array = Array(string2)
        let length = min(string1Array.count, string2Array.count)
        for i in 0..<length {
            if string1Array[i] == string2Array[i] {
                commonPrefix.append(string1Array[i])
            } else {
                break
            }
        }
        return commonPrefix
    }
    /*
     Given an integer columnNumber, return its corresponding column title as it appears in an Excel sheet.

     For example:

     A -> 1
     B -> 2
     C -> 3
     ...
     Z -> 26
     AA -> 27
     AB -> 28
     ...


     Example 1:

     Input: columnNumber = 1
     Output: "A"
     Example 2:

     Input: columnNumber = 28
     Output: "AB"
     Example 3:

     Input: columnNumber = 701
     Output: "ZY"


     Constraints:

     1 <= columnNumber <= 231 - 1
     */

    func convertToTitle(_ columnNumber: Int) -> String {
        var columnNumber = columnNumber
        var string: String = ""
        while columnNumber > 0 {
            let remainder = columnNumber % 26
            if remainder == 0 {
                string.insert("Z", at: string.startIndex)
                columnNumber = (columnNumber / 26) - 1
            } else {
                let charIndex = remainder - 1 + Int(("A" as UnicodeScalar).value)
                string.insert(Character(UnicodeScalar(charIndex)!), at: string.startIndex)
                // string.append()
                columnNumber /= 26
            }
            
        }
        // string = String(string.reversed())
        return string
    }

    /*
     You are given two strings word1 and word2. Merge the strings by adding letters in alternating order, starting with word1. If a string is longer than the other, append the additional letters onto the end of the merged string.

     Return the merged string.



     Example 1:

     Input: word1 = "abc", word2 = "pqr"
     Output: "apbqcr"
     Explanation: The merged string will be merged as so:
     word1:  a   b   c
     word2:    p   q   r
     merged: a p b q c r
     Example 2:

     Input: word1 = "ab", word2 = "pqrs"
     Output: "apbqrs"
     Explanation: Notice that as word2 is longer, "rs" is appended to the end.
     word1:  a   b
     word2:    p   q   r   s
     merged: a p b q   r   s
     Example 3:

     Input: word1 = "abcd", word2 = "pq"
     Output: "apbqcd"
     Explanation: Notice that as word1 is longer, "cd" is appended to the end.
     word1:  a   b   c   d
     word2:    p   q
     merged: a p b q c   d


     Constraints:

     1 <= word1.length, word2.length <= 100
     word1 and word2 consist of lowercase English letters.

     */

    func mergeAlternately(word1: String, word2: String) -> String {
        let word1 = Array(word1)
        let word2 = Array(word2)
        let count1 = word1.count
        let count2 = word2.count
        var result = ""
        var i = 0, j = 0
        while i < count1 && j < count2 {
            result.append(word1[i])
            result.append(word2[j])
            i += 1
            j += 1
        }
        if i < count1 {
            result.append(String(word1[i..<count1]))
        } else {
            result.append(String(word2[j..<count2]))
        }

        return result
    }
